#[test]
fn test_a_source_bitset_has_one_class() {
    crate::testport::assert_eq(cal_class(sr_text()), 0, "text layer");
    crate::testport::assert_eq(cal_class(sr_hidden_text()), 0, "hidden text is the text layer's");
    crate::testport::assert_eq(cal_class(sr_text() | sr_infer()), 0, "text and inferred structure: the text layer's");
    crate::testport::assert_eq(cal_class(sr_ocr()), 1, "OCR");
    crate::testport::assert_eq(cal_class(sr_ocr() | sr_infer()), 1, "OCR and inferred structure: OCR's");
    crate::testport::assert_eq(cal_class(sr_text() | sr_ocr()), 2, "both");
    crate::testport::assert_eq(cal_class(sr_hidden_text() | sr_ocr()), 2, "hidden text and OCR: both");
    crate::testport::assert_eq(cal_class(sr_infer()), 3, "inferred only");
    crate::testport::assert_eq(cal_class(sr_struct()), 3, "the tagged tree only: neither");
    crate::testport::assert_eq(cal_class(0), 3, "no source");
}
