#[test]
fn test_the_table_is_sorted_and_monotone_in_the_raw_score() {
    // Rows are [kind class raw-lo calibrated], sorted by kind, class, raw-lo; within one kind and class the raw-lo rises strictly
    // and the calibrated value never falls (isotonic), and a value is a confidence.
    let n: i32 = 19;
    let mut i: i32 = 1;
    crate::testport::assert_that(n > 0, "the table has a row (the identity table has one that no node matches)");
    while i < n {
        let k0: i32 = CD_ROWS[((i - 1) * 4 + 0) as usize];
        let c0: i32 = CD_ROWS[((i - 1) * 4 + 1) as usize];
        let k1: i32 = CD_ROWS[(i * 4 + 0) as usize];
        let c1: i32 = CD_ROWS[(i * 4 + 1) as usize];
        crate::testport::assert_that((k0 < k1) || ((k0 == k1) && (c0 <= c1)), "sorted by kind then class");
        if (k0 == k1) && (c0 == c1) {
            crate::testport::assert_that(CD_ROWS[((i - 1) * 4 + 2) as usize] < CD_ROWS[(i * 4 + 2) as usize], "raw-lo rises within a kind and class");
            crate::testport::assert_that(CD_ROWS[((i - 1) * 4 + 3) as usize] <= CD_ROWS[(i * 4 + 3) as usize], "calibrated never falls with the raw score");
        }
        crate::testport::assert_that((CD_ROWS[(i * 4 + 3) as usize] >= 0) && (CD_ROWS[(i * 4 + 3) as usize] <= 1000), "a calibrated value is 0..1000");
        i += 1;
    }
}
#[test]
fn test_every_step_of_the_table_answers_with_its_own_value() {
    // At a step's raw-lo (and one above it, if that is still below the next step) the lookup is the step's value,
    // for the class the row names (an `any` row is read through a class that has no row of its own: a class code
    // the table never names, 9, falls back to `any`).
    let n: i32 = 19;
    let mut i: i32 = 0;
    while i < n {
        if CD_ROWS[(i * 4 + 1) as usize] == -1 {
            crate::testport::assert_eq_at(cal_lookup(CD_ROWS[(i * 4 + 0) as usize], 9, CD_ROWS[(i * 4 + 2) as usize]), CD_ROWS[(i * 4 + 3) as usize], "an any-row at its raw-lo", i);
        }
        i += 1;
    }
}
#[test]
fn test_the_lookup_clamps_at_both_ends_of_a_step_function() {
    // Below a row's first step the first step's value; above the last the last's (no extrapolation).
    let n: i32 = 19;
    let mut i: i32 = 0;
    while i < n {
        if CD_ROWS[(i * 4 + 1) as usize] == -1 {
            let kind: i32 = CD_ROWS[(i * 4 + 0) as usize];
            let mut first_v: i32 = -1;
            let mut last_v: i32 = -1;
            let mut j: i32 = 0;
            while j < n {
                if (CD_ROWS[(j * 4 + 0) as usize] == kind) && (CD_ROWS[(j * 4 + 1) as usize] == -1) {
                    if first_v < 0 {
                        first_v = CD_ROWS[(j * 4 + 3) as usize];
                    }
                    last_v = CD_ROWS[(j * 4 + 3) as usize];
                }
                j += 1;
            }
            crate::testport::assert_eq_at(cal_lookup(kind, 9, 0), first_v, "raw 0 takes the first step", i);
            crate::testport::assert_eq_at(cal_lookup(kind, 9, 1000), last_v, "raw 1000 takes the last step", i);
        }
        i += 1;
    }
}
#[test]
fn test_a_block_flagged_script_unread_is_written_at_its_raw_score() {
    // D1610: the map clamps at its first step, so a raw 100 on OCR text is written as the lowest confidence of text the engine READ; the engine's guess at a script it
    // cannot read keeps its raw score, and so do the inlines under it
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(nodes, attrs, regions, text, pages, ledger, layout);
    let p1: i32 = node_new(nodes, nk_paragraph(), 0);
    let t1: i32 = node_new(nodes, nk_text(), p1);
    let p2: i32 = node_new(nodes, nk_paragraph(), 0);
    node_add_src(nodes, p1, sr_ocr());
    node_set_conf(nodes, p1, 100);
    node_add_flag(nodes, p1, fl_script_unread());
    node_add_src(nodes, t1, sr_ocr());
    node_set_conf(nodes, t1, 100);
    node_add_src(nodes, p2, sr_ocr());
    node_set_conf(nodes, p2, 100);
    let mapped: i32 = cal_conf(nk_paragraph(), sr_ocr(), 100);
    let mut want: i32 = 100;
    if mapped < 100 {
        want = mapped;
    }
    crate::testport::assert_eq(cal_node_conf(nodes, p1), want, "the flagged block: its raw score, when the map would give more");
    crate::testport::assert_that(cal_node_conf(nodes, p1) <= 100, "never above it");
    crate::testport::assert_that(cal_node_conf(nodes, t1) <= 100, "the text under it too");
    crate::testport::assert_eq(cal_node_conf(nodes, p2), mapped, "a block no one flagged is calibrated as it was");
}
